function load(kind){const i=document.createElement('input');i.type='file';i.accept=kind==='csv'?'.csv':'.json';i.onchange=async()=>{try{const f=i.files[0];if(!f)return;recovery=null;if(kind==='csv'){if(!data)throw Error('先に初回指示JSONを読み込んでください');const b=await f.arrayBuffer();let text=new TextDecoder('utf-8').decode(b);if(text.includes('\ufffd'))text=new TextDecoder('shift_jis').decode(b);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b))).map(x=>x.toString(16).padStart(2,'0')).join('');pendingCsv=N.csvEvent(data.file,text,f.name,f.lastModified,hash);pendingSharedCsv={text,name:f.name,modified:f.lastModified};msg='CSVを読みました。Driveで最新を選んだことを確認してください。';}else{const x=JSON.parse(await f.text());if(x.type==='instruction'){N.instruction(x);if(worker&&x.assignee!==worker)throw Error('この画面は'+(worker==='OWNER'?'オーナー':worker+'さん')+'用です。担当の違うJSONは読み込めません');if(f.name!==N.filename(x))throw Error('ファイル名が受付番号と一致しません');for(let p=data?.file.carry?.file;p;p=p.carry?.file){if(p.receiptId===x.receiptId)throw Error('終了した旧受付です。最新JSONを使用してください');}if(data?.past?.some(p=>p.file.receiptId===x.receiptId))throw Error('終了した旧受付です。最新JSONを使用してください');if(data){if(JSON.stringify(data.file)===JSON.stringify(x)){msg='同じ指示です。現在の記録を保持しました。';render();return;}const states=N.replay(data.file,data.events).items;const linked=x.carry&&JSON.stringify(x.carry.file)===JSON.stringify(data.file)&&JSON.stringify(x.carry.events)===JSON.stringify(data.events);if(x.carry&&!linked)offerRecovery(x,f.name,'引継ぎ基準と現在の履歴が一致しません。バックアップを提出してから復元できます。');if(!((worker==='OWNER'||owner)&&linked)&&(dirty()||!data.submitted||(!linked&&states.some(j=>!['owner','hold','sold','unlisted'].includes(j.stage))))){if(x.carry)offerRecovery(x,f.name,'現在の作業結果の保存・提出が未確認です。バックアップを提出してから復元できます。');throw Error('現在の作業結果を保存・提出してから追加JSONを読み込んでください。オーナーは入口の「JSONを読み込む」をご利用ください');}}save({file:x,events:[],saved:null,attempted:null,submitted:false,past:data?[...(data.past||[]),{file:data.file,events:data.events}]:[]});mode=owner?'owner':'staff';msg='担当商品と引き継ぎ履歴を読み込みました。最新CSVの確認後に作業できます。';}else{if(!data)throw Error('オーナーは発行した指示JSONを先に読み込んでください');const got=N.receive(data.file,data.events,x,f.name);save({...data,events:got.events,...(owner||!worker?{receivedAt:new Date().toISOString()}:{})});mode=owner||!worker?'owner':'staff';msg=got.duplicate?'同じ結果は受領済みです。二重処理しません。':'受付番号と全操作履歴を照合し、受領しました。';}}}catch(e){msg=e.message;}render();syncSharedCsv();};i.click();}
function holdFields(parent,j){const type=select('確認できない内容',[['','選んでください'],...HoldReasons.options(j.platform)],parent),memo=input('詳しい状況（その他は必須）','text',parent);return()=>{if(!type.value)throw Error('確認できない内容を選んでください');if(type.value==='other'&&!memo.value.trim())throw Error('何を確認できなかったか入力してください');const label=HoldReasons.options(j.platform).find(x=>x[0]===type.value)[1];return label+(memo.value.trim()?'：'+memo.value.trim():'');};}
function displayDate(value){const n=Date.parse(value);return Number.isFinite(n)?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(n):'未確認';}function link(text,url,p){const a=el('a',text,p);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}function copy(text,p,label,previewLabel='コメント全文を見る'){const b=el('button',label,p);b.dataset.copyStep='1';b.dataset.copyText=text;const pasteHint=/^\d+$/.test(text)?el('small',data?.file.items.find(x=>x.id===selected)?.platform==='mercari'?'価格欄を右クリック → 貼り付け':'価格欄で Ctrl＋V を押して貼り付け',p):null;if(pasteHint){pasteHint.hidden=true;pasteHint.className='paste-hint';}b.onclick=async()=>{if(!csvReady()){msg='日付が変わりました。最新Shops CSVを読み込んでください';render();return;}try{await navigator.clipboard.writeText(text);if(pasteHint)pasteHint.hidden=false;b.dataset.copied='1';b.classList.add('copy-selected');b.textContent='✓ '+label;guideSteps();b.classList.remove('copy-flash');void b.offsetWidth;b.classList.add('copy-flash');b.onanimationend=()=>b.classList.remove('copy-flash');}catch{const t=el('textarea','',p);t.value=text;t.readOnly=true;t.select();msg='選択した内容をコピーしてください。';$('message').textContent=msg;}};if(previewLabel&&!/^\d+$/.test(text)){const details=el('details','',p);el('summary',previewLabel,details);el('p',text,details);}}
